client_script:
frappe.web_form.after_load = function () {

    setTimeout(() => {

        console.log("=== SUPPLIER DOCUMENT SCRIPT START ===");

        // Get the actual table field
        let field = frappe.web_form.fields_dict["custom_supplier_documents"];

        if (!field) {
            console.error("custom_supplier_documents field NOT FOUND");
            return;
        }

        let table = field.grid;

        if (!table) {
            console.error("Supplier Documents grid NOT FOUND");
            return;
        }

        // -----------------------------------------
        // DEFAULT DOCUMENTS
        // -----------------------------------------

        let docs = [
            "PAN Card",
            "GST Certificate",
            "Cancelled Cheque",
            "Bank Proof",
            "Company Registration",
            "Other"
        ];

        // -----------------------------------------
        // CLEAR EXISTING ROWS
        // -----------------------------------------

        frappe.web_form.doc.custom_supplier_documents = [];

        // -----------------------------------------
        // ADD DEFAULT ROWS
        // -----------------------------------------

        docs.forEach(function (doc_name) {

            frappe.web_form.doc.custom_supplier_documents.push({

                doctype: "Supplier Registration Document",

                document_type: doc_name,

                document_file: "",

                document_status: "Pending",

                remarks: ""

            });

        });

        // -----------------------------------------
        // BIND DATA TO GRID
        // -----------------------------------------

        table.df.data = frappe.web_form.doc.custom_supplier_documents;

        // -----------------------------------------
        // REFRESH GRID
        // -----------------------------------------

        table.refresh();

        // -----------------------------------------
        // LOCK DOCUMENT TYPE
        // -----------------------------------------

        table.update_docfield_property(
            "document_type",
            "read_only",
            1
        );

        // -----------------------------------------
        // LOCK STATUS
        // -----------------------------------------

        table.update_docfield_property(
            "document_status",
            "read_only",
            1
        );

        // -----------------------------------------
        // REFRESH AGAIN
        // -----------------------------------------

        table.refresh();

        console.log(
            "Supplier Documents Loaded:",
            frappe.web_form.doc.custom_supplier_documents
        );

        console.log("=== SUPPLIER DOCUMENT SCRIPT COMPLETE ===");

    }, 1500);

};

custom_css:
/* Supplier Documents - Compact Premium UI */

[data-fieldname="custom_supplier_documents"] {
    margin: 18px 0;
}

[data-fieldname="custom_supplier_documents"] .frappe-control-label {
    font-size: 17px !important;
    font-weight: 600 !important;
    color: #1f2937 !important;
    margin-bottom: 8px !important;
}

/* Compact table */
[data-fieldname="custom_supplier_documents"] .grid {
    border: 1px solid #e5e7eb !important;
    border-radius: 10px !important;
    overflow: hidden !important;
    background: #fff !important;
}

[data-fieldname="custom_supplier_documents"] .grid-heading-row {
    background: #f8fafc !important;
    border-bottom: 1px solid #e5e7eb !important;
}

[data-fieldname="custom_supplier_documents"] .grid-heading-row .col {
    font-size: 12px !important;
    font-weight: 600 !important;
    color: #64748b !important;
    padding: 9px 10px !important;
}

/* Rows */
[data-fieldname="custom_supplier_documents"] .grid-row {
    min-height: 48px !important;
    border-bottom: 1px solid #f1f5f9 !important;
}

[data-fieldname="custom_supplier_documents"] .grid-row:last-child {
    border-bottom: 0 !important;
}

[data-fieldname="custom_supplier_documents"] .grid-row:hover {
    background: #f8fbff !important;
}

[data-fieldname="custom_supplier_documents"] .grid-row .col {
    min-height: 48px !important;
    display: flex;
    align-items: center;
}

/* Document name */
[data-fieldname="custom_supplier_documents"]
[data-fieldname="document_type"] .control-value {
    font-size: 13px !important;
    font-weight: 600 !important;
    color: #334155 !important;
}

/* Attach button */
[data-fieldname="custom_supplier_documents"]
[data-fieldname="document_file"] .btn {
    padding: 5px 10px !important;
    font-size: 12px !important;
    border-radius: 6px !important;
    border: 1px solid #dbe3ef !important;
    color: #2563eb !important;
    background: #fff !important;
}

[data-fieldname="custom_supplier_documents"]
[data-fieldname="document_file"] .btn:hover {
    background: #eff6ff !important;
}

/* Status */
[data-fieldname="custom_supplier_documents"]
[data-fieldname="document_status"] .control-value {
    display: inline-block !important;
    padding: 4px 9px !important;
    border-radius: 20px !important;
    background: #fff7ed !important;
    color: #c2410c !important;
    font-size: 11px !important;
    font-weight: 600 !important;
}

/* Remarks */
[data-fieldname="custom_supplier_documents"]
[data-fieldname="remarks"] input {
    height: 30px !important;
    border-radius: 6px !important;
    font-size: 12px !important;
}

/* Hide Add Row */
[data-fieldname="custom_supplier_documents"] .grid-add-row {
    display: none !important;
}

/* Hide delete controls */
[data-fieldname="custom_supplier_documents"] .grid-delete-row {
    display: none !important;
}

/* Mobile */
@media (max-width: 768px) {
    [data-fieldname="custom_supplier_documents"] .grid {
        overflow-x: auto !important;
    }

    [data-fieldname="custom_supplier_documents"] .grid-heading-row,
    [data-fieldname="custom_supplier_documents"] .grid-row {
        min-width: 700px !important;
    }
}
